'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts, over two orders "a" and "b".
// Each order has at most one message in transit at a time (Reserve, then its
// answer, then possibly Release), so the network is one slot per order and
// DELIVER(order) delivers that slot; delivering a before b or b before a covers
// every arrival order.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CAPACITY = 3;
const KEYS = ['available', 'reserved', 'statusA', 'qtyA', 'msgA', 'statusB', 'qtyB', 'msgB'];
const INITIAL_STATE = {
  available: 1, reserved: 0,
  statusA: 'none', qtyA: 0, msgA: 'none',
  statusB: 'none', qtyB: 0, msgB: 'none',
};

const suffix = (order) => (order === 'a' ? 'A' : 'B');

// Assign the changed keys and frame every other key as unchanged.
const commit = (next, unchanged, changes) => {
  for (const [k, v] of Object.entries(changes)) next[k] = v;
  const rest = KEYS.filter((k) => !(k in changes));
  if (rest.length) unchanged(...rest);
};

const intent = (domain, schema) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      statusA: { type: 'string' },
      qtyA: { type: 'number' },
      msgA: { type: 'string' },
      statusB: { type: 'string' },
      qtyB: { type: 'number' },
      msgB: { type: 'string' },
    },
    actions: {
      PLACE: intent(
        ['a', 'b'].flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
        { order: { type: 'string', required: true }, qty: { type: 'number', required: true } }
      ),
      CANCEL: intent([{ order: 'a' }, { order: 'b' }], { order: { type: 'string', required: true } }),
      EXPIRE: intent([{ order: 'a' }, { order: 'b' }], { order: { type: 'string', required: true } }),
      RESTOCK: intent([{}], {}),
      DELIVER: intent([{ order: 'a' }, { order: 'b' }], { order: { type: 'string', required: true } }),
    },
    acceptors: {
      PLACE: (model) => (proposal, { reject, next, unchanged }) => {
        const S = suffix(proposal.order);
        if (proposal.qty !== 1 && proposal.qty !== 2) return reject('bad-qty');
        if (model['status' + S] !== 'none') return reject('order-exists');
        commit(next, unchanged, { ['status' + S]: 'pending', ['qty' + S]: proposal.qty, ['msg' + S]: 'Reserve' });
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        const S = suffix(proposal.order);
        const status = model['status' + S];
        if (status === 'none') return reject('unknown-order');
        if (status === 'confirmed') {
          return commit(next, unchanged, { ['status' + S]: 'cancelled', ['msg' + S]: 'Release' });
        }
        if (status === 'pending') return commit(next, unchanged, { ['status' + S]: 'cancelling' });
        return reject('not-cancellable');
      },
      EXPIRE: (model) => (proposal, { reject, next, unchanged }) => {
        const S = suffix(proposal.order);
        const status = model['status' + S];
        if (status === 'none') return reject('unknown-order');
        if (status !== 'confirmed') return reject('not-expirable');
        commit(next, unchanged, { ['status' + S]: 'expired', ['msg' + S]: 'Release' });
      },
      RESTOCK: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.available + model.reserved >= CAPACITY) return reject('inventory-full');
        commit(next, unchanged, { available: model.available + 1 });
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const S = suffix(proposal.order);
        const msg = model['msg' + S];
        const status = model['status' + S];
        const qty = model['qty' + S];
        if (msg === 'none') return reject('nothing-in-transit');
        if (msg === 'Reserve') {
          if (model.available >= qty) {
            return commit(next, unchanged, {
              available: model.available - qty, reserved: model.reserved + qty, ['msg' + S]: 'Reserved',
            });
          }
          return commit(next, unchanged, { ['msg' + S]: 'OutOfStock' });
        }
        if (msg === 'Release') {
          return commit(next, unchanged, {
            available: model.available + qty, reserved: model.reserved - qty, ['msg' + S]: 'none',
          });
        }
        if (msg === 'Reserved') {
          if (status === 'pending') return commit(next, unchanged, { ['status' + S]: 'confirmed', ['msg' + S]: 'none' });
          if (status === 'cancelling') {
            return commit(next, unchanged, { ['status' + S]: 'cancelled', ['msg' + S]: 'Release' });
          }
          return commit(next, unchanged, { ['msg' + S]: 'none' });
        }
        // OutOfStock
        if (status === 'pending') return commit(next, unchanged, { ['status' + S]: 'rejected', ['msg' + S]: 'none' });
        if (status === 'cancelling') return commit(next, unchanged, { ['status' + S]: 'cancelled', ['msg' + S]: 'none' });
        return commit(next, unchanged, { ['msg' + S]: 'none' });
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

