        if (status === 'pending') return commit(next, unchanged, { ['status' + S]: 'rejected', ['msg' + S]: 'none' });
        if (status === 'cancelling') return commit(next, unchanged, { ['status' + S]: 'cancelled', ['msg' + S]: 'none' });
        return commit(next, unchanged, { ['msg' + S]: 'none' });
      },
    },
    reactors: [],
  },
});

