import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('place, confirm, cancel', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a'))!.status, 'cancelled');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 1.5)).ok, false);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.equal(await h.order('zz'), null);
  assert.equal((await h.place('a', 2)).ok, true);
  assert.equal((await h.place('a', 1)).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'rejected');
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
});

test('cancel while pending, reserved answer', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.cancel('a');
  assert.equal((await h.order('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  const [m] = await h.inFlight();
  await h.deliver(m.id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  const [r] = await h.inFlight();
  assert.equal(r.action, 'Reserved');
  await h.deliver(r.id);
  assert.equal((await h.order('a'))!.status, 'cancelled');
  const [rel] = await h.inFlight();
  assert.deepEqual(rel.data, { qty: 1 });
  await h.deliver(rel.id);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('cancel while pending, out of stock', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('expire', async () => {
  const h = await createHost();
  assert.equal((await h.expire('zz')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('stocktake', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  await h.place('b', 1);
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.equal((await h.restock()).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('b'))!.status, 'rejected');
  // A Release is still taken while closed.
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.equal((await h.restock()).ok, true);
  await h.place('c', 2);
  await h.deliverAll();
  assert.equal((await h.order('c'))!.status, 'confirmed');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
});

test('competing orders in any order', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.place('b', 1);
  const msgs = await h.inFlight();
  await h.deliver(msgs[1].id);
  await h.deliverAll();
  assert.equal((await h.order('b'))!.status, 'confirmed');
  assert.equal((await h.order('a'))!.status, 'rejected');
});

