// SAM v2 strict-profile spec of src/host.impl.ts, over two orders "a" and "b".
// Each order has at most one message in transit at a time (Reserve, then its
// answer, then possibly Release), so the network is one slot per order and
// DELIVER(order) delivers that slot; delivering a before b or b before a covers
// every arrival order.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CAPACITY = 3;
const KEYS = ['available', 'reserved', 'open', 'statusA', 'qtyA', 'msgA', 'statusB', 'qtyB', 'msgB'];
const INITIAL_STATE = {
  available: 1, reserved: 0, open: true,
  statusA: 'none', qtyA: 0, msgA: 'none',
  statusB: 'none', qtyB: 0, msgB: 'none',
};

const suffix = (order) => (order === 'a' ? 'A' : 'B');

// Assign the changed keys and frame every other key as unchanged.
const commit = (next, unchanged, changes) => {
  for (const [k, v] of Object.entries(changes)) next[k] = v;
  const rest = KEYS.filter((k) => !(k in changes));
  if (rest.length) unchanged(...rest);
};

