// Rules the brief requires, over the two-order spec in orders.spec.cjs.

const ORDERS = ['A', 'B'];
const STATUSES = ['none', 'pending', 'confirmed', 'rejected', 'cancelling', 'cancelled', 'expired'];
const quiet = (s) => ORDERS.every((o) => s['msg' + o] === 'none');

// Units that belong to an order: reserved for it by the inventory and not yet
// given back (its Reserved answer in transit, confirmed, or its Release in transit).
const owned = (s, o) => {
  const st = s['status' + o];
  const msg = s['msg' + o];
  if (st === 'confirmed' || msg === 'Reserved' || msg === 'Release') return s['qty' + o];
  return 0;
};

export const stateInvariants = [
  { name: 'stock-bounds', pred: (s) => s.available >= 0 && s.reserved >= 0 && s.available + s.reserved <= 3 },
  { name: 'valid-orders', pred: (s) => ORDERS.every((o) =>
      STATUSES.includes(s['status' + o]) &&
      (s['status' + o] === 'none' ? s['qty' + o] === 0 : s['qty' + o] === 1 || s['qty' + o] === 2)) },
  // Units are never lost or invented, even with messages in transit.
  { name: 'reserved-is-owned', pred: (s) => s.reserved === ORDERS.reduce((n, o) => n + owned(s, o), 0) },
  // Once no message is in transit, reserved units are exactly those of confirmed orders.
  { name: 'quiescent-reserved-equals-confirmed', pred: (s) => !quiet(s) ||
      s.reserved === ORDERS.reduce((n, o) => n + (s['status' + o] === 'confirmed' ? s['qty' + o] : 0), 0) },
  // A confirmed order has its units reserved.
  { name: 'confirmed-has-units', pred: (s) => ORDERS.every((o) => s['status' + o] !== 'confirmed' || s.reserved >= s['qty' + o]) },
  // A cancelled, expired, rejected or cancelling order holds no units once nothing is in transit for it.
  { name: 'settled-orders-hold-nothing', pred: (s) => ORDERS.every((o) =>
      !['cancelled', 'expired', 'rejected', 'cancelling'].includes(s['status' + o]) || s['msg' + o] !== 'none' || owned(s, o) === 0) },
];

const TERMINAL = ['rejected', 'cancelled', 'expired'];
export const transitionInvariants = [
  // While closed the inventory reserves nothing and is not restocked; Release is still taken.
  { name: 'closed-reserves-nothing', pred: (pre, action, data, post) =>
      pre.open || post.reserved <= pre.reserved && post.available + post.reserved === pre.available + pre.reserved },
  { name: 'closed-answers-out-of-stock', pred: (pre, action, data, post) => pre.open || ORDERS.every((o) =>
      pre['msg' + o] !== 'Reserve' || post['msg' + o] !== 'Reserved') },
  { name: 'closed-takes-release', pred: (pre, action, data, post) => ORDERS.every((o) =>
      !(action === 'DELIVER' && data.order.toUpperCase() === o && pre['msg' + o] === 'Release') ||
      post.reserved === pre.reserved - pre['qty' + o]) },
  // Only CLOSE and OPEN change whether the inventory is open.
  { name: 'open-toggled-by-commands', pred: (pre, action, data, post) =>
      post.open === pre.open || (action === 'CLOSE' && pre.open) || (action === 'OPEN' && !pre.open) },
  // Only EXPIRE on a confirmed order makes it expired.
  { name: 'expire-only-confirmed', pred: (pre, action, data, post) => ORDERS.every((o) =>
      pre['status' + o] === 'expired' || post['status' + o] !== 'expired' ||
      (action === 'EXPIRE' && data.order.toUpperCase() === o && pre['status' + o] === 'confirmed')) },
  // An expired order accepts no command: no command changes anything about it.
  { name: 'expired-accepts-nothing', pred: (pre, action, data, post) => ORDERS.every((o) =>
      pre['status' + o] !== 'expired' || !['PLACE', 'CANCEL', 'EXPIRE'].includes(action) || data.order.toUpperCase() !== o ||
      ['status', 'qty', 'msg'].every((k) => post[k + o] === pre[k + o]) && post.available === pre.available && post.reserved === pre.reserved) },
  // Terminal orders never change status.
  { name: 'terminal-orders-stay', pred: (pre, action, data, post) => ORDERS.every((o) =>
      !TERMINAL.includes(pre['status' + o]) || post['status' + o] === pre['status' + o]) },
  // Only the inventory's Reserved answer confirms an order.
  { name: 'confirm-only-on-reserved', pred: (pre, action, data, post) => ORDERS.every((o) =>
      pre['status' + o] === 'confirmed' || post['status' + o] !== 'confirmed' ||
      (action === 'DELIVER' && data.order.toUpperCase() === o && pre['msg' + o] === 'Reserved')) },
  // Restock adds exactly one unit; nothing else changes the total held.
  { name: 'total-changes-only-by-restock', pred: (pre, action, data, post) => {
      const delta = post.available + post.reserved - (pre.available + pre.reserved);
      return action === 'RESTOCK' ? delta === 0 || delta === 1 : delta === 0;
    } },
];

export default { stateInvariants, transitionInvariants };

