const STATUSES = ['none', 'pending', 'confirmed', 'rejected', 'cancelling', 'cancelled', 'expired'];

const releasing = (s, o) => s['rel1' + o] + 2 * s['rel2' + o];
const quietFor = (s, o) => s['msg' + o] === 'none' && releasing(s, o) === 0;
const quiet = (s) => ORDERS.every((o) => quietFor(s, o));
const targets = (action, data, o) => typeof data.order === 'string' && data.order.toUpperCase() === o;

